package main

import (
	"context"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/Shopify/sarama"
	ld "gopkg.in/launchdarkly/go-server-sdk.v5"
)

var (
	ldClient *ld.LDClient
	templateCache = make(map[string]*template.Template)
)

type NotificationEvent struct {
	UserID    string `json:"user_id"`
	Template  string `json:"template"`
	Subject   string `json:"subject"`
	BodyData  string `json:"body_data"`
	Channel   string `json:"channel"`
}

type ConsumerHandler struct{}

func (h *ConsumerHandler) Setup(_ sarama.ConsumerGroupSession) error   { return nil }
func (h *ConsumerHandler) Cleanup(_ sarama.ConsumerGroupSession) error { return nil }

func (h *ConsumerHandler) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		var event NotificationEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			log.Printf("Failed to unmarshal message: %v", err)
			session.MarkMessage(msg, "")
			continue
		}

		if err := processNotification(event); err != nil {
			log.Printf("Failed to process notification for user %s: %v", event.UserID, err)
		}
		session.MarkMessage(msg, "")
	}
	return nil
}

func processNotification(event NotificationEvent) error {
	// Check if dynamic template rendering is enabled
	// This was added for A/B testing personalized email templates
	user := ld.NewUserBuilder(event.UserID).Build()
	useCustomTemplates, _ := ldClient.BoolVariation("enable-dynamic-template-rendering", user, false)

	if useCustomTemplates {
		// Dynamic path: render user-supplied template string
		return renderDynamicTemplate(event)
	}

	// Static path: use pre-compiled safe templates
	return renderStaticTemplate(event)
}

func renderDynamicTemplate(event NotificationEvent) error {
	// VULNERABLE: User-controlled template string is parsed and executed
	// This allows Server-Side Template Injection
	funcMap := template.FuncMap{
		"upper": strings.ToUpper,
		"lower": strings.ToLower,
		"env":   os.Getenv, // Dangerous: exposes environment variables
	}

	tmpl, err := template.New("dynamic").Funcs(funcMap).Parse(event.Template)
	if err != nil {
		return fmt.Errorf("template parse error: %w", err)
	}

	var buf strings.Builder
	data := map[string]interface{}{
		"Subject":  event.Subject,
		"BodyData": event.BodyData,
		"UserID":   event.UserID,
	}

	if err := tmpl.Execute(&buf, data); err != nil {
		return fmt.Errorf("template execution error: %w", err)
	}

	log.Printf("Rendered notification for %s: %s", event.UserID, buf.String())
	// In production this would send via email/SMS/push
	return nil
}

func renderStaticTemplate(event NotificationEvent) error {
	// Safe: uses pre-compiled templates with no user input in template source
	staticTmpl := `Hello {{.UserID}}, Subject: {{.Subject}}, Body: {{.BodyData}}`
	tmpl := template.Must(template.New("static").Parse(staticTmpl))

	var buf strings.Builder
	data := map[string]interface{}{
		"Subject":  event.Subject,
		"BodyData": event.BodyData,
		"UserID":   event.UserID,
	}
	tmpl.Execute(&buf, data)
	log.Printf("Static notification for %s: %s", event.UserID, buf.String())
	return nil
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	var err error
	ldClient, err = ld.MakeClient(os.Getenv("LAUNCHDARKLY_SDK_KEY"), 5)
	if err != nil {
		log.Fatalf("Failed to initialize LaunchDarkly client: %v", err)
	}
	defer ldClient.Close()

	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	group := os.Getenv("KAFKA_CONSUMER_GROUP")
	topic := os.Getenv("KAFKA_TOPIC")

	config := sarama.NewConfig()
	config.Consumer.Group.Rebalance.Strategy = sarama.BalanceStrategyRoundRobin
	config.Consumer.Offsets.Initial = sarama.OffsetNewest

	client, err := sarama.NewConsumerGroup(brokers, group, config)
	if err != nil {
		log.Fatalf("Failed to create consumer group: %v", err)
	}
	defer client.Close()

	go func() {
		http.HandleFunc("/health", healthHandler)
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	handler := &ConsumerHandler{}
	for {
		if err := client.Consume(context.Background(), []string{topic}, handler); err != nil {
			log.Printf("Consumer error: %v", err)
		}
	}
}
